CREATE TABLE {prefix}_agent_revision (scope_id TEXT NOT NULL, id TEXT NOT NULL, generation BIGINT NOT NULL, data {json} NOT NULL, created_at {timestamptz} NOT NULL DEFAULT {now}, PRIMARY KEY (scope_id, id, generation)); INSERT INTO {prefix}_agent_revision (scope_id, id, generation, data) SELECT scope_id, id, generation, data FROM {prefix}_agent ON CONFLICT (scope_id, id, generation) DO NOTHING; CREATE OR REPLACE FUNCTION {prefix}_capture_agent_revision() RETURNS TRIGGER AS $$ BEGIN INSERT INTO {prefix}_agent_revision (scope_id, id, generation, data) VALUES (NEW.scope_id, NEW.id, NEW.generation, NEW.data) ON CONFLICT (scope_id, id, generation) DO NOTHING; RETURN NEW; END; $$ LANGUAGE plpgsql; CREATE TRIGGER {prefix}_agent_revision_capture AFTER INSERT OR UPDATE ON {prefix}_agent FOR EACH ROW EXECUTE FUNCTION {prefix}_capture_agent_revision()
